public static void addLink(RefRecId _recId, MobCartID _cartId, InventQty _qty)
{
    MobCartPicklistLink link;

    link.CartID			= _cartId;
    link.RefRecId		= _recId;
    link.InventQty		= _qty;
    link.insert();
}

public static boolean exists(RefRecId _recId, MobCartID _cartId)
{
    MobCartPicklistLink link;

    select firstonly link where link.RefRecId == _recId && link.CartID == _cartId;

    return link.recid;
}

public static void removeLinks(MobCartID _cartId)
{
    MobCartPicklistLink link;

    delete_from link
        where link.CartID == _cartId;
}

public static InventQty totalQty(RefRecId _recId, MobCartID _cartId)
{
    WMSOrderTrans			accOrderTrans;
    MobCartPicklistLink		link;
    InventQty				qtyRet;
    InventDimId				orgDimID;
    ItemId					orgItemId;
    boolean					isReserved;

    select firstonly accOrderTrans where accOrderTrans.RecId == _recId;
    orgDimID	= accOrderTrans.inventDimId;
    orgItemId	= accOrderTrans.itemId;
    isReserved	= accOrderTrans.isReserved;
    //select sum(InventQty) from link where link.RefRecId == _recId && link.CartID == _cartId;

    while select link where link.CartID == _cartId
        join accOrderTrans where link.refRecID == accOrderTrans.RecId && accOrderTrans.inventDimId == orgDimID && accOrderTrans.itemId == orgItemId && (!isReserved || accOrderTrans.RecId == _recId)
    {
        qtyRet += link.InventQty;
    }
    return qtyRet;
}

public static InventQty totalQtyBOM(RefRecId _recId, MobCartID _cartId)
{
    ProdJournalBOM			accOrderTrans;
    MobCartPicklistLink		link;
    InventQty				qtyRet;
    InventDimId				orgDimID;
    ItemId					orgItemId;
    boolean					isReserved;

    select firstonly accOrderTrans where accOrderTrans.RecId == _recId;
    orgDimID	= accOrderTrans.inventDimId;
    orgItemId	= accOrderTrans.itemId;
    //select sum(InventQty) from link where link.RefRecId == _recId && link.CartID == _cartId;

    while select link where link.CartID == _cartId
        join accOrderTrans where link.refRecID == accOrderTrans.RecId && accOrderTrans.inventDimId == orgDimID && accOrderTrans.itemId == orgItemId && accOrderTrans.RecId == _recId
    {
        qtyRet += link.InventQty;
    }
    return qtyRet;
}
